#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "correlation.h"


/* Array initialization. */
static
void init_array (int m,
		 int n,
		 DATA_TYPE *float_n,
		 DATA_TYPE POLYBENCH_2D(data,N,M,n,m))
{
  int i, j;

  *float_n = (DATA_TYPE)N;

  for (i = 0; i < N; i++)
    for (j = 0; j < M; j++)
      data[i][j] = (DATA_TYPE)(i*j)/M + i;

}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m,
		 DATA_TYPE POLYBENCH_2D(corr,M,M,m,m))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("corr");
  for (i = 0; i < m; i++)
    for (j = 0; j < m; j++) {
      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation [[gnu::flatten, gnu::noinline]] (int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* sqrt(float_n) is invariant; compute it once. */
  const DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

  /* Per-column normalization denominator:
     denom[j] = sqrt(float_n) * stddev[j].
     Sized by compile-time M; in this benchmark m == M. */
  DATA_TYPE denom[M];

#pragma scop
  /* --------------------------------------------------------------------
   * Step 1: compute column means.
   *
   * Original order:
   *   for (j)
   *     mean[j] = 0;
   *     for (i)
   *       mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *
   * New order:
   *   - zero all means
   *   - traverse data row-wise (i outer, j inner)
   *   - scale by float_n
   *
   * For each fixed j, the contributions data[0][j], data[1][j], ...,
   * data[N-1][j] are still accumulated in strictly increasing i order,
   * so the sequence of floating-point operations for mean[j] is
   * preserved while improving spatial locality (row-major access).
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      mean[j] += data[i][j];

  for (j = 0; j < _PB_M; j++)
    mean[j] /= float_n;

  /* --------------------------------------------------------------------
   * Step 2: compute column standard deviations.
   *
   * Original order:
   *   for (j)
   *     stddev[j] = 0;
   *     for (i)
   *       stddev[j] += (data[i][j] - mean[j])^2;
   *     stddev[j] /= float_n;
   *     stddev[j] = sqrt(stddev[j]);
   *     if (stddev[j] <= eps) stddev[j] = 1;
   *
   * New order:
   *   - zero all stddev
   *   - traverse data row-wise (i outer, j inner), accumulating
   *     (data[i][j] - mean[j])^2 in increasing i order
   *   - finalize each stddev[j] as in the original code
   *
   * Again, for each j the accumulation order along i is identical to
   * the original, but memory accesses follow the row-major layout.
   * ------------------------------------------------------------------ */
  for (j = 0; j < _PB_M; j++)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        DATA_TYPE diff = data[i][j] - mean[j];
        stddev[j] += diff * diff;
      }

  for (j = 0; j < _PB_M; j++)
    {
      stddev[j] /= float_n;
      stddev[j] = SQRT_FUN(stddev[j]);
      /* Handle near-zero std. dev. values to avoid division by zero. */
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];

      /* Precompute the denominator used in normalization for this column.
         This is exactly the same product that the original code formed
         inside the normalization loop, but computed once per column. */
      denom[j] = sqrt_float_n * stddev[j];
    }

  /* --------------------------------------------------------------------
   * Step 3: center and reduce the column vectors.
   *
   * The loop order (i outer, j inner) already matches the row-major
   * layout of 'data', so we keep it. The only change is that the
   * product sqrt(float_n) * stddev[j] has been precomputed in
   * denom[j], avoiding redundant multiplications and sqrt calls while
   * preserving the original division by that exact product.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_N; i++)
    for (j = 0; j < _PB_M; j++)
      {
        data[i][j] -= mean[j];
        data[i][j] /= denom[j];
      }

  /* --------------------------------------------------------------------
   * Step 4: compute the m x m correlation matrix.
   *
   * Original order:
   *   for (i = 0; i < M-1; i++) {
   *     corr[i][i] = 1;
   *     for (j = i+1; j < M; j++) {
   *       corr[i][j] = 0;
   *       for (k = 0; k < N; k++)
   *         corr[i][j] += data[k][i] * data[k][j];
   *       corr[j][i] = corr[i][j];
   *     }
   *   }
   *   corr[M-1][M-1] = 1;
   *
   * New order:
   *   for each i:
   *     - set corr[i][i] = 1
   *     - zero corr[i][j] for j > i
   *     - for each k, traverse row data[k][i..M-1] contiguously and
   *       update corr[i][j] for all j > i
   *     - copy upper triangle row i into lower triangle column i
   *
   * For each pair (i, j) with i < j, the partial sums for corr[i][j]
   * are still accumulated in strictly increasing k order, exactly as in
   * the original code. Only the traversal order over (i, j) pairs is
   * changed to improve data locality and reduce the total number of
   * matrix element loads.
   * ------------------------------------------------------------------ */
  for (i = 0; i < _PB_M; i++)
    {
      corr[i][i] = SCALAR_VAL(1.0);

      /* Initialize upper-triangular entries in row i. */
      for (j = i+1; j < _PB_M; j++)
        corr[i][j] = SCALAR_VAL(0.0);

      /* Accumulate dot products row by row. */
      for (k = 0; k < _PB_N; k++)
        {
          DATA_TYPE data_ki = data[k][i];
          for (j = i+1; j < _PB_M; j++)
            corr[i][j] += data_ki * data[k][j];
        }

      /* Fill the symmetric lower-triangular counterparts. */
      for (j = i+1; j < _PB_M; j++)
        corr[j][i] = corr[i][j];
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
  POLYBENCH_FREE_ARRAY(stddev);

  return 0;
}
