}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* PolyBench provides problem-size macros that may differ from m/n. */
  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

#pragma scop
  /* 1. Compute column means.
   *
   * Original code:
   *   for (j)
   *     mean[j] = 0;
   *     for (i)
   *       mean[j] += data[i][j];
   *
   * Here we traverse the data row-by-row (i outer, j inner) to improve
   * spatial locality. For each column j, the sequence of additions over i
   * is still in increasing i order, so the floating-point sum per column
   * is bitwise identical to the original.
   */
  for (j = 0; j < Mdim; j++)
    mean[j] = SCALAR_VAL(0.0);

  for (i = 0; i < Ndim; i++)
    for (j = 0; j < Mdim; j++)
      mean[j] += data[i][j];

  for (j = 0; j < Mdim; j++)
    mean[j] /= float_n;


  /* 2. Compute column standard deviations.
   *
   * We again use row-major traversal for better cache behavior.
   * For each column j, we still add terms corresponding to i = 0..Ndim-1
   * in that order, preserving the original summation order.
   */
  for (j = 0; j < Mdim; j++)
    stddev[j] = SCALAR_VAL(0.0);

  for (i = 0; i < Ndim; i++)
    for (j = 0; j < Mdim; j++)
    {
      DATA_TYPE diff = data[i][j] - mean[j];
      stddev[j] += diff * diff;
    }

  for (j = 0; j < Mdim; j++)
  {
    stddev[j] /= float_n;
    stddev[j] = SQRT_FUN(stddev[j]);
    /* Handle near-zero std. dev. values to avoid division by (almost) zero. */
    if (stddev[j] <= eps)
      stddev[j] = SCALAR_VAL(1.0);
  }

  /* 3. Center and reduce the column vectors.
   *
   * We precompute sqrt_n once and also precompute the per-column
   * denominators sqrt_n * stddev[j] outside of the main data loop.
   * This removes redundant work while preserving the exact arithmetic
   * performed per element (one subtraction followed by one division).
   *
   * Access is row-major (i outer, j inner) for good locality.
   */
  const DATA_TYPE sqrt_n = SQRT_FUN(float_n);

  /* Per-column normalization factors: denom[j] = sqrt_n * stddev[j]. */
  DATA_TYPE denom[_PB_M];
  for (j = 0; j < Mdim; j++)
    denom[j] = sqrt_n * stddev[j];

  for (i = 0; i < Ndim; i++)
    for (j = 0; j < Mdim; j++)
    {
      DATA_TYPE diff = data[i][j] - mean[j];
      data[i][j] = diff / denom[j];
    }

  /* 4. Calculate the m * m correlation matrix.
   *
   * The mathematical definition is:
   *   corr[i][j] = sum_k data[k][i] * data[k][j],  for i != j
   *   corr[i][i] = 1
   *
   * Original code performs, for each (i,j), an inner loop over k. That
   * repeatedly streams the same data columns from memory.
   *
   * Here we instead:
   *   - Initialize the upper triangle corr[i][j] (i < j) to 0.
   *   - Accumulate dot products by streaming over k (rows) and updating
   *     all (i,j) pairs for that row. This improves data reuse: each
   *     row of 'data' is streamed once per k and reused from registers /
   *     L1 cache within the inner loops.
   *   - Finally, copy the upper triangle to the lower and set the
   *     diagonal to exactly 1.0, matching the original semantics.
   *
   * For each (i,j) pair, the partial sums are still added in order of
   * increasing k (0 .. Ndim-1), so the final floating-point result for
   * each corr[i][j] is identical to the original implementation.
   */

  /* Initialize upper triangle (i < j) to 0.0. */
  for (i = 0; i < Mdim; i++)
    for (j = i + 1; j < Mdim; j++)
      corr[i][j] = SCALAR_VAL(0.0);

  /* Accumulate dot products for the upper triangle. */
  for (k = 0; k < Ndim; k++)
  {
    for (i = 0; i < Mdim - 1; i++)
    {
      const DATA_TYPE data_ki = data[k][i];
      for (j = i + 1; j < Mdim; j++)
        corr[i][j] += data_ki * data[k][j];
    }
  }

  /* Symmetrize and set diagonal to exactly 1.0. */
  for (i = 0; i < Mdim; i++)
  {
    corr[i][i] = SCALAR_VAL(1.0);
    for (j = i + 1; j < Mdim; j++)
      corr[j][i] = corr[i][j];
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE float_n;
  POLYBENCH_2D_ARRAY_DECL(data,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(corr,DATA_TYPE,M,M,m,m);
  POLYBENCH_1D_ARRAY_DECL(mean,DATA_TYPE,M,m);
  POLYBENCH_1D_ARRAY_DECL(stddev,DATA_TYPE,M,m);

  /* Initialize array(s). */
  init_array (m, n, &float_n, POLYBENCH_ARRAY(data));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_correlation (m, n, float_n,
		      POLYBENCH_ARRAY(data),
		      POLYBENCH_ARRAY(corr),
		      POLYBENCH_ARRAY(mean),
		      POLYBENCH_ARRAY(stddev));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, POLYBENCH_ARRAY(corr)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(data);
  POLYBENCH_FREE_ARRAY(corr);
  POLYBENCH_FREE_ARRAY(mean);
