      if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, corr[i][j]);
    }
  POLYBENCH_DUMP_END("corr");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_correlation[[gnu::flatten, gnu::noinline]](int m, int n,
			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  /* Small value used to guard against near-zero standard deviations. */
  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Loop bounds used throughout the kernel. */
  const int Mdim = _PB_M;
  const int Ndim = _PB_N;

  /* Frequently used scalar factors, precomputed once. */
  const DATA_TYPE inv_float_n   = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_float_n  = SQRT_FUN(float_n);

#pragma scop

  /* --------------------------------------------------------------------
   * Step 1: Compute the mean of each column.
   *
   * Original code:
   *   for (j) {
   *     mean[j] = 0;
   *     for (i) mean[j] += data[i][j];
   *     mean[j] /= float_n;
   *   }
   *
   * Here, we keep exactly the same sequence of operations for each mean[j],
   * but traverse the data in row-major order for better cache locality:
   *   - First zero all means.
   *   - Then accumulate column sums row by row.
   *   - Finally scale by 1/float_n.
   * For any fixed j, the additions still occur in the order i = 0..Ndim-1,
   * so floating-point round-off behavior per column is preserved.
   * --------------------------------------------------------------------
   */

  /* Initialize means to zero. */
  for (j = 0; j < Mdim; ++j)
    mean[j] = SCALAR_VAL(0.0);

  /* Accumulate column sums in a row-major friendly way. */
  for (i = 0; i < Ndim; ++i)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < Mdim; ++j)
        mean[j] += data_row[j];
    }

  /* Normalize by float_n. */
  for (j = 0; j < Mdim; ++j)
    mean[j] *= inv_float_n;


  /* --------------------------------------------------------------------
   * Step 2: Compute the standard deviation of each column.
   *
   * Original code:
   *   for (j) {
   *     stddev[j] = 0;
   *     for (i) stddev[j] += (data[i][j] - mean[j])^2;
   *     stddev[j] /= float_n;
   *     stddev[j] = sqrt(stddev[j]);
   *     if (stddev[j] <= eps) stddev[j] = 1.0;
   *   }
   *
   * We again keep the per-column operation order identical while changing
   * only the traversal order to row-major to improve locality:
   *   - Zero all stddev.
   *   - Accumulate squared differences row by row.
   *   - Finalize each stddev[j] as in the original.
   *
   * Afterward, we multiply stddev[j] by sqrt(float_n) once per column.
   * This precomputes the denominator used later in normalization:
   *       denom_j = sqrt(float_n) * stddev[j]
   * The original code recomputed sqrt(float_n) inside the inner loop for
   * every element; we reuse the same value without changing the exact
   * per-column denominator.
   * --------------------------------------------------------------------
   */

  /* Initialize variances to zero. */
  for (j = 0; j < Mdim; ++j)
    stddev[j] = SCALAR_VAL(0.0);

  /* Accumulate squared differences. */
  for (i = 0; i < Ndim; ++i)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < Mdim; ++j)
        {
          DATA_TYPE diff = data_row[j] - mean[j];
          stddev[j] += diff * diff;
        }
    }

  /* Finalize stddev values and turn them into per-column denominators. */
  for (j = 0; j < Mdim; ++j)
    {
      /* stddev[j] currently holds sum_k (data[k][j] - mean[j])^2. */
      stddev[j] *= inv_float_n;          /* divide by float_n        */
      stddev[j] = SQRT_FUN(stddev[j]);   /* take square root         */

      /* Handle near-zero stddev to avoid division by a very small number. */
      stddev[j] = stddev[j] <= eps ? SCALAR_VAL(1.0) : stddev[j];

      /* Precompute sqrt(float_n) * stddev[j] once per column.
         In the original implementation, this product was recomputed for
         every (i,j) during normalization. Here we store the result directly
         into stddev[j] to be used as the normalization denominator. */
      stddev[j] *= sqrt_float_n;
    }


  /* --------------------------------------------------------------------
   * Step 3: Center and normalize the columns.
   *
   * Original code:
   *   for (i)
   *     for (j) {
   *       data[i][j] -= mean[j];
   *       data[i][j] /= sqrt(float_n) * stddev[j];
   *     }
   *
   * After Step 2 above, stddev[j] now equals exactly
   *     sqrt(float_n) * (original stddev[j])
   * so the transformation below performs:
   *     data[i][j] = (data[i][j] - mean[j]) / stddev[j];
   * which is algebraically and numerically equivalent to the original
   * expression, but avoids recomputing sqrt(float_n) for every element.
   * --------------------------------------------------------------------
   */

  for (i = 0; i < Ndim; ++i)
    {
      DATA_TYPE *data_row = data[i];
      for (j = 0; j < Mdim; ++j)
        {
          data_row[j] -= mean[j];
          data_row[j] /= stddev[j];
        }
    }


  /* --------------------------------------------------------------------
   * Step 4: Compute the M x M correlation matrix.
   *
   * Original code (simplified):
   *   for (i = 0; i < M-1; ++i) {
   *     corr[i][i] = 1.0;
   *     for (j = i+1; j < M; ++j) {
   *       corr[i][j] = 0.0;
   *       for (k = 0; k < N; ++k)
   *         corr[i][j] += data[k][i] * data[k][j];
   *       corr[j][i] = corr[i][j];
   *     }
   *   }
   *   corr[M-1][M-1] = 1.0;
   *
   * We exploit the symmetry more effectively by:
   *   - Initializing only the upper triangle (i < j) to 0.
   *   - Accumulating contributions row by row:
   *         for (k) for (i) for (j>i) corr[i][j] += data[k][i]*data[k][j]
   *   - Setting the diagonal to 1.0 and mirroring the upper triangle.
   *
   * For any fixed pair (i, j) with i < j, the sequence of updates to
   * corr[i][j] still occurs with k running from 0 to Ndim-1 in order,
   * just as in the original code. Only the traversal order of independent
   * (i, j) pairs is changed, so the floating-point behavior per entry is
   * preserved, while greatly improving data locality:
   *   - data[k][*] is accessed row-wise (contiguous in memory),
   *   - we reuse data[k][i] for all j > i within the same row.
   * --------------------------------------------------------------------
   */

  /* Initialize upper triangle (excluding diagonal) to zero. */
  for (i = 0; i < Mdim - 1; ++i)
    {
      DATA_TYPE *corr_row_i = corr[i];
      for (j = i + 1; j < Mdim; ++j)
        corr_row_i[j] = SCALAR_VAL(0.0);
    }

  /* Accumulate correlation coefficients row by row. */
  for (k = 0; k < Ndim; ++k)
    {
      DATA_TYPE *data_row = data[k];
      for (i = 0; i < Mdim - 1; ++i)
        {
          const DATA_TYPE x_i = data_row[i];
          DATA_TYPE *corr_row_i = corr[i];

          /* Only compute for j > i (upper triangle). */
          for (j = i + 1; j < Mdim; ++j)
            corr_row_i[j] += x_i * data_row[j];
        }
    }

  /* Set diagonal to 1.0 and mirror the upper triangle to the lower. */
  for (i = 0; i < Mdim; ++i)
    {
      corr[i][i] = SCALAR_VAL(1.0);
      DATA_TYPE *corr_row_i = corr[i];
      for (j = i + 1; j < Mdim; ++j)
        corr[j][i] = corr_row_i[j];
    }

#pragma endscop

}


