			DATA_TYPE float_n,
			DATA_TYPE POLYBENCH_2D(data,N,M,n,m),
			DATA_TYPE POLYBENCH_2D(corr,M,M,m,m),
			DATA_TYPE POLYBENCH_1D(mean,M,m),
			DATA_TYPE POLYBENCH_1D(stddev,M,m))
{
  int i, j, k;

  const DATA_TYPE eps = SCALAR_VAL(0.1);

  /* Create restrict-qualified local aliases for better optimization.
     After these are defined, the original parameter names are not
     used anymore. This allows the compiler to safely assume that
     these arrays do not alias each other. */
