  DATA_TYPE (*restrict corrR)[m]   = corr;
  DATA_TYPE *restrict meanR        = mean;
  DATA_TYPE *restrict stddevR      = stddev;

  /* Hoist invariants. */
  const int _m = _PB_M;
  const int _n = _PB_N;
  const DATA_TYPE inv_float_n  = SCALAR_VAL(1.0) / float_n;
  const DATA_TYPE sqrt_float_n = SQRT_FUN(float_n);

#pragma scop
