    stddevR[j] = SCALAR_VAL(0.0);

  for (i = 0; i < _n; i++)
    {
      DATA_TYPE *restrict data_row = dataR[i];
      for (j = 0; j < _m; j++)
        {
          DATA_TYPE diff = data_row[j] - meanR[j];
          stddevR[j] += diff * diff;
        }
    }

  for (j = 0; j < _m; j++)
    {
      stddevR[j] *= inv_float_n;
      stddevR[j] = SQRT_FUN(stddevR[j]);
      /* Handle near-zero std. dev. values to avoid division by zero. */
      stddevR[j] = stddevR[j] <= eps ? SCALAR_VAL(1.0) : stddevR[j];
    }

