   * 3. Center and reduce the column vectors.
   *
   * We precompute sqrt(float_n) once and reuse it.  The original code
   * evaluated SQRT_FUN(float_n) inside the inner loop; hoisting this
   * does not change the arithmetic expression
   *   (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
   * but avoids redundant work.
   * ------------------------------------------------------------------*/
  for (i = 0; i < _n; i++)
    {
      DATA_TYPE *restrict data_row = dataR[i];
      for (j = 0; j < _m; j++)
        {
          data_row[j] -= meanR[j];
          data_row[j] /= (sqrt_float_n * stddevR[j]);
        }
    }

  /* --------------------------------------------------------------------
   * 4. Calculate the m * m correlation matrix.
   *
   * Original code (schematically):
   *   for (i)
   *     corr[i][i] = 1;
   *     for (j > i)
   *       corr[i][j] = 0;
   *       for (k)
   *         corr[i][j] += data[k][i] * data[k][j];
   *       corr[j][i] = corr[i][j];
   *
   * That is column-oriented (k inner), so every access to 'data'
   * is strided by 'm', and each column pair (i,j) scans all rows
   * separately.
   *
   * Here we switch to a row-wise accumulation:
   *
   *   - For k from 0..n-1 (rows)
   *       for i
   *         for j > i
   *           corr[i][j] += data[k][i] * data[k][j];
   *
   *   - After accumulation, we set the diagonal to 1.0 and copy the
   *     upper triangle into the lower triangle.
   *
   * For every fixed pair (i,j), the sequence of updates over k is
   * still performed in the order k = 0..n-1, starting from 0.0, so
   * the partial sums for each correlation entry are computed in the
   * same order as in the original algorithm.  Only the interleaving
   * between different (i,j) pairs changes, which does not affect
   * the result because different pairs are independent.
   *
   * This transformation gives:
   *   - Unit-stride access to 'data' (row-major).
   *   - Better reuse of each loaded row across many (i,j) pairs.
   * ------------------------------------------------------------------*/
  if (_n > 0)
    {
