         data[0][*] instead of an explicit 0.0 + first_term is
         exactly equivalent, because 0.0 + x == x for any finite x. */
      DATA_TYPE *restrict data_row0 = dataR[0];
      for (i = 0; i < _m - 1; i++)
        {
          DATA_TYPE d0_i = data_row0[i];
          for (j = i + 1; j < _m; j++)
            corrR[i][j] = d0_i * data_row0[j];
        }

      /* Accumulate remaining rows. */
      for (k = 1; k < _n; k++)
        {
          DATA_TYPE *restrict data_row = dataR[k];
          for (i = 0; i < _m - 1; i++)
            {
              DATA_TYPE dki = data_row[i];
              for (j = i + 1; j < _m; j++)
                corrR[i][j] += dki * data_row[j];
            }
        }
    }
