     This matches the original behavior where corr[i][i] is forced
     to 1.0 and corr[j][i] is set equal to corr[i][j]. */
  for (i = 0; i < _m; i++)
    {
      corrR[i][i] = SCALAR_VAL(1.0);
      for (j = i + 1; j < _m; j++)
        corrR[j][i] = corrR[i][j];
    }
#pragma endscop

